<!doctype html><html><head><meta charset="utf-8"><title>Receipt {{ $transaction->reference_number }}</title><style>body{font-family:Arial,sans-serif;max-width:700px;margin:40px auto;color:#222}.receipt{border:1px solid #ddd;padding:32px}h1{margin:0 0 8px}table{width:100%;border-collapse:collapse;margin-top:25px}td{padding:10px 0;border-bottom:1px solid #eee}.right{text-align:right}.muted{color:#666}@media print{button{display:none}}</style></head><body><button onclick="window.print()">Print</button><div class="receipt"><p class="muted">Membership transaction receipt</p><h1>{{ $transaction->reference_number }}</h1><p class="muted">{{ $transaction->created_at->format('F j, Y g:i A') }}</p><table><tr><td>Member</td><td class="right">{{ $transaction->member->full_name }}</td></tr><tr><td>Member number</td><td class="right">{{ $transaction->member->member_number }}</td></tr><tr><td>Transaction</td><td class="right">{{ ucfirst($transaction->transaction_type) }}</td></tr><tr><td>Membership</td><td class="right">{{ $transaction->category }} · {{ $transaction->level }}</td></tr><tr><td>Status</td><td class="right">{{ $transaction->status_label }}</td></tr><tr><td>Payment method</td><td class="right">{{ $transaction->latestPayment?->payment_method ?: '—' }}</td></tr><tr><td><strong>Total</strong></td><td class="right"><strong>₱{{ number_format((float)$transaction->amount,2) }}</strong></td></tr></table></div></body></html>
